import { REGION_IDS } from "../domain/contracts";
import type { RegionRaster } from "./atlas";
import { TEXEL_COUNT } from "./layers";
import { base64ToBytes, bytesToBase64 } from "./png";
import { REGION_RASTER_BODY_MAP_VERSION, REGION_RASTER_RLE } from "./region-raster-data";

/**
 * The region-ID raster of the current body map, embedded as run-length data so the shared reducer runs synchronously
 * in the browser and in Node without loading the full body asset. Generated by `npm run body:generate`; a test checks it
 * against the atlas rasterized from `public/body/mannequin-v2.json`.
 * Format: repeated [region byte (REGION_IDS index + 1, 0 = invalid), run length as LEB128 varint], row-major.
 */
export function encodeRegionRaster(regionOf: Int8Array): string {
  const bytes: number[] = [];
  for (let texel = 0; texel < TEXEL_COUNT;) {
    const value = regionOf[texel];
    let run = 1;
    while (texel + run < TEXEL_COUNT && regionOf[texel + run] === value) run++;
    bytes.push(value + 1);
    for (let n = run; ; ) { const low = n & 0x7f; n >>>= 7; if (n) bytes.push(low | 0x80); else { bytes.push(low); break; } }
    texel += run;
  }
  return bytesToBase64(Uint8Array.from(bytes));
}

export function decodeRegionRaster(encoded: string): RegionRaster {
  const bytes = base64ToBytes(encoded);
  const regionOf = new Int8Array(TEXEL_COUNT);
  const regionTexelCount = new Uint32Array(REGION_IDS.length);
  let texel = 0, i = 0;
  while (i < bytes.length) {
    const value = bytes[i++] - 1;
    let run = 0, shift = 0;
    for (;;) { const byte = bytes[i++]; run |= (byte & 0x7f) << shift; if (!(byte & 0x80)) break; shift += 7; }
    if (value >= REGION_IDS.length || texel + run > TEXEL_COUNT) throw new Error("Corrupt region raster.");
    regionOf.fill(value, texel, texel + run);
    if (value >= 0) regionTexelCount[value] += run;
    texel += run;
  }
  if (texel !== TEXEL_COUNT) throw new Error("Corrupt region raster.");
  return { regionOf, regionTexelCount };
}

let cached: RegionRaster | undefined;
/** The region raster for the current body-map version (decoded once). */
export function getRegionRaster(): RegionRaster {
  cached ??= decodeRegionRaster(REGION_RASTER_RLE);
  return cached;
}
export { REGION_RASTER_BODY_MAP_VERSION };
